using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.FNZ.Cuentas;namespace GraphApi.Services.FNZ.Cuentas{    public class CuentasService : ICuentasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public CuentasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadCuentas>> GetCuentas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM fnz.Cuentas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadCuentas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetCuentasDynamic(            int? cuentaID,            string? cuenta,            string? tipo,            decimal? saldo,            int? responsableUsuarioID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "CuentaID, Cuenta, Tipo, Saldo, ResponsableUsuarioID, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM fnz.Cuentas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (cuentaID.HasValue)            {                vSql.Append(" AND CuentaID = @CuentaID");                vParameters.Add("CuentaID",cuentaID);            }            if (!string.IsNullOrWhiteSpace(cuenta))            {                vSql.Append(" AND Cuenta LIKE @Cuenta");                vParameters.Add("Cuenta",$"%{cuenta}%");            }            if (!string.IsNullOrWhiteSpace(tipo))            {                vSql.Append(" AND Tipo LIKE @Tipo");                vParameters.Add("Tipo",$"%{tipo}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadCuentas> CreateCuentas(clCreateCuentas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO fnz.Cuentas                (Cuenta, Tipo, Saldo, ResponsableUsuarioID, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@Cuenta, @Tipo, @Saldo, @ResponsableUsuarioID, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.Cuenta,                objInput.Tipo,                objInput.Saldo,                objInput.ResponsableUsuarioID,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT CuentaID, Cuenta, Tipo, Saldo, ResponsableUsuarioID, bEliminado                FROM fnz.Cuentas (NOLOCK)                WHERE CuentaID = @CuentaID;";            var vReadParams = new { CuentaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadCuentas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Cuenta con ID {vNewId}.");            return vCreated;        }        public async Task<clReadCuentas?> UpdateCuentas(clUpdateCuentas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("CuentaID", objInput.CuentaID);            if (objInput.Cuenta is not null)            {                vSets.Add("Cuenta = @Cuenta");                vParameters.Add("Cuenta", objInput.Cuenta);            }            if (objInput.Tipo is not null)            {                vSets.Add("Tipo = @Tipo");                vParameters.Add("Tipo", objInput.Tipo);            }            if (objInput.Saldo != null)            {                vSets.Add("Saldo = @Saldo");                vParameters.Add("Saldo", objInput.Saldo);            }            if (objInput.ResponsableUsuarioID != null)            {                vSets.Add("ResponsableUsuarioID = @ResponsableUsuarioID");                vParameters.Add("ResponsableUsuarioID", objInput.ResponsableUsuarioID);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE fnz.Cuentas                SET {vSetClause}                WHERE CuentaID = @CuentaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT CuentaID, Cuenta, Tipo, Saldo, ResponsableUsuarioID, bEliminado                FROM fnz.Cuentas (NOLOCK)                WHERE CuentaID = @CuentaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadCuentas>(sSelect, new {  objInput.CuentaID });        }        public async Task<bool> DeleteCuentas(int nCuentasID)        {            const string sSql = @"                DELETE FROM fnz.Cuentas                WHERE CuentaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nCuentasID });            return vAffected > 0;        }    }}